<template>
 <main class="research">
  <header class="research-hero"><div><span class="eyebrow">BUY LESS. CHOOSE BETTER.</span><h1>把数码低价，变成有依据的好选题。</h1><p>采集商品、核对配置、比较价格，再写一篇对读者有用的购买指南。</p></div><button @click="load" :disabled="busy">刷新研究台 ↻</button></header>
  <div class="status-note" v-if="error" role="alert">{{ error }}</div><div class="success-note" v-if="notice" role="status">{{ notice }}</div>
  <section class="research-stats"><article><span>商品样本</span><strong>{{ listings.length }}</strong><small>保存原链接和采集时间</small></article><article><span>分析报告</span><strong>{{ reports.length }}</strong><small>按型号、配置和成色比较</small></article><article><span>文章草稿</span><strong>{{ articles.length }}</strong><small>证据稿与 AI 稿分别标记</small></article><article><span>来源雷达</span><strong>{{ sources.filter(s=>s.status==='available').length }}<i>/ {{ sources.length }}</i></strong><small>当前可用 / 已登记</small></article></section>
  <nav class="research-tabs" aria-label="研究模块导航"><button v-for="item in tabs" :key="item.id" :class="{selected:tab===item.id}" @click="tab=item.id">{{ item.label }}</button></nav>
  <template v-if="tab==='market'">
   <section class="research-panel"><div class="panel-heading"><div><h2>闲鱼数码选题池</h2><p>低价只是线索，配置、成色和验机条件才决定是否值得继续看。</p></div><span class="badge">{{ capabilities.xianyu_mode==='authorized_provider'?'授权数据接口':'公开页面采集' }}</span></div>
    <form class="search-line" @submit.prevent="search"><input v-model="query" placeholder="例如：iPhone 15 256GB、MacBook Air M2" minlength="2" maxlength="80" aria-label="闲鱼搜索关键词"><button :disabled="busy || !canWrite || query.trim().length<2">采集商品</button><button type="button" class="secondary" @click="showImport=!showImport">{{ showImport?'收起导入':'导入商品资料' }}</button></form>
    <p class="hint">{{ capabilities.xianyu_note }} 挂牌价不能当作成交价。</p>
    <div v-if="showImport" class="import-area"><div class="import-tabs"><button :class="{selected:importMode==='form'}" @click="importMode='form'">录入一个商品</button><button :class="{selected:importMode==='json'}" @click="importMode='json'">批量 JSON 导入</button></div>
     <form v-if="importMode==='form'" class="listing-form" @submit.prevent="saveListing">
      <label>商品标题<input v-model="form.title" required maxlength="240" placeholder="保留原商品标题"></label><label>商品原链接<input v-model="form.url" required type="url" placeholder="https://www.goofish.com/item?id=..."></label>
      <label>型号<input v-model="form.model" required placeholder="iPhone 15"></label><label>准确配置<input v-model="form.variant" required placeholder="国行 / 256GB / 其他关键配置"></label>
      <label>挂牌价（元）<input v-model.number="form.price" type="number" min="0.01" step="0.01" required></label><label>运费（元）<input v-model.number="form.shipping" type="number" min="0" step="0.01" required></label>
      <label>类别<select v-model="form.category"><option value="phone">手机</option><option value="tablet">平板</option><option value="laptop">电脑</option><option value="gpu">显卡</option><option value="camera">相机</option><option value="other">其他</option></select></label>
      <label>成色<select v-model="form.condition"><option value="unknown">尚未核实</option><option value="good">良好</option><option value="fair">明显使用痕迹</option><option value="new">全新</option><option value="parts">故障 / 配件</option></select></label>
      <label>卖家代号<input v-model="form.seller_ref" placeholder="用于去重，保存时会脱敏"></label><label>电池健康（可空）<input v-model="form.battery_health" type="number" min="0" max="100"></label>
      <label>维修情况<select v-model="form.repair_status"><option value="unknown">未确认</option><option value="seller_claims_original">卖家声称原装</option><option value="verified_original">已核验原装</option><option value="repaired">有维修</option></select></label>
      <label>观察时间<input v-model="form.observed_at" type="datetime-local" required></label><label class="wide">商品描述<textarea v-model="form.description" rows="3" placeholder="保留影响判断的成色、配件、维修和售后说明"></textarea></label>
      <label class="check"><input v-model="form.inspection_available" type="checkbox">确认支持验机</label><button :disabled="busy || !canWrite">保存商品资料</button>
     </form>
     <div v-else><p>使用标准字段导入已有资料，重复商品会更新。原链接、型号、配置、价格和带时区的观察时间必须保留。</p><textarea v-model="importText" rows="8" spellcheck="false" aria-label="商品 JSON" placeholder='{"items":[{"external_id":"商品ID","title":"商品标题","model":"准确型号","variant":"准确配置","price":1000,"url":"https://www.goofish.com/item?id=商品ID","observed_at":"2026-10-18T08:00:00+08:00"}]}'></textarea><button :disabled="busy || !canWrite" @click="importJson">导入并校验</button></div>
    </div>
   </section>
   <section class="research-panel"><div class="panel-heading"><div><h2>商品证据</h2><p>{{ listings.length ? '选择同一型号和配置，生成可复查的价格分析。' : '还没有真实商品样本。采集或导入后，商品会显示在这里。' }}</p></div><button :disabled="busy || !filteredListings.length || !canWrite" @click="createReport">分析这些商品</button></div><label class="filter-label">筛选型号<input v-model="filter" placeholder="输入型号或配置，只分析筛选后的商品"></label>
    <div class="listing-grid"><article v-for="item in filteredListings.slice(0,60)" :key="item.id" class="listing-card"><span class="badge">{{ item.model }} · {{ item.variant }}</span><h3>{{ item.title }}</h3><strong class="price">¥{{ Number(item.price)+Number(item.shipping) }} <small>含运费挂牌价</small></strong><p>{{ conditionLabel[item.condition] || item.condition }} · {{ item.battery_health===null?'电池未知':`电池 ${item.battery_health}%` }}</p><p class="hint">{{ formatDate(item.observed_at) }}</p><div class="card-actions"><a :href="item.url" target="_blank" rel="noopener noreferrer">查看原商品 ↗</a><button class="link-button" :disabled="busy || !canWrite" @click="remove(item.id)">移除</button></div></article></div>
   </section>
   <section v-for="report in reports.filter(r=>r.report.kind!=='news')" :key="report.id" class="research-panel"><div class="panel-heading"><div><span class="eyebrow">RESEARCH / {{ formatDate(report.created_at) }}</span><h2>{{ report.title }}</h2></div><div class="button-row"><button class="secondary" :disabled="busy || !canWrite" @click="createArticle(report.id,false)">生成分析稿</button><button :disabled="busy || !canWrite || !capabilities.ai_configured" @click="createArticle(report.id,true)">AI 写作</button></div></div><p class="hint" v-if="!capabilities.ai_configured">文章模型尚未配置，当前可生成包含价格与风险依据的分析稿。</p>
    <div v-for="group in report.report.groups" :key="group.model+group.variant+group.condition" class="comparison"><h3>{{ group.model }} · {{ group.variant }} <span class="badge">样本置信度：{{ group.confidence }}</span></h3><p>{{ group.sample_count }} 个可比样本 / {{ group.seller_count }} 个卖家 · 挂牌中位价 {{ group.median_asking_price===null?'未知':`¥${group.median_asking_price}` }}</p><div v-for="item in group.candidates.slice(0,5)" :key="item.external_id" class="candidate"><div><strong>{{ item.verdict }}</strong><a :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.title }}</a><small>{{ item.risks.length?item.risks.join('；'):'支持继续核实设备与交易条件' }}</small></div><b>¥{{ item.total_price }}<small>{{ item.discount_percent===null?'无法比较':`较中位价 ${item.discount_percent>=0?'低':'高'} ${Math.abs(item.discount_percent)}%` }}</small></b></div></div><p class="method">{{ report.report.method }} 挂牌价不是成交价，样本结论不能替代验机。</p>
   </section>
  </template>
  <template v-if="tab==='sources'"><section class="research-panel"><div class="panel-heading"><div><h2>来源雷达</h2><p>公开 RSS / Atom 资讯与数码评测线索。可配置每 6 小时自动更新，也可手动检查；失败保留真实原因。</p></div></div><div class="source-grid"><article v-for="source in sources" :key="source.id" class="source-card"><span :class="['source-state',source.status]">{{ sourceState[source.status] || '未检查' }}</span><h3>{{ source.name }}</h3><p>{{ source.category }} · {{ source.count || 0 }} 条近期资讯</p><p class="hint">{{ source.detail || formatDate(source.checked_at) }}</p><div class="card-actions"><a :href="source.url" target="_blank" rel="noopener noreferrer">查看来源 ↗</a><button class="link-button" :disabled="busy || !canWrite" @click="refreshSource(source.id)">检查更新</button></div></article></div></section><section class="research-panel"><h2>最新选题线索</h2><article v-for="item in news" :key="item.url" class="news-item"><a :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.title }}</a><p>{{ item.summary.slice(0,220) }}</p><div class="card-actions"><small>{{ item.source_id }} · {{ formatDate(item.published_at) }}</small><button class="link-button" :disabled="busy || !canWrite || !capabilities.ai_configured" @click="writeNews(item)">以此为选题 · AI 写作 ↗</button></div></article></section></template>
  <template v-if="tab==='articles'"><section class="research-panel" v-if="!articles.length"><h2>从研究报告开始一篇文章</h2><p>先采集商品并分析，再生成有依据的选购稿。没有真实样本时不会编造推荐榜单。</p></section><section v-for="article in articles" :key="article.id" class="research-panel"><div class="panel-heading"><div><span class="badge">{{ article.mode==='ai'?(article.status==='needs_review'?'AI 稿 · 待核对':'AI 请求 · 保留证据稿'):'证据分析稿' }}</span><h2>{{ article.title }}</h2><p>{{ articleState[article.status] || article.status }} · {{ formatDate(article.created_at) }}</p></div><div class="button-row"><button class="secondary" @click="download(article.id,'markdown')">导出 Markdown</button><button v-if="article.status==='ready' || article.status==='needs_review'" :disabled="busy || !canWrite" @click="selectForPublication(article.id)">投递这篇文章</button><button @click="download(article.id,'html')">导出排版 HTML</button></div></div><p v-if="article.error" class="status-note">{{ article.error }}</p><button v-if="article.status==='response_invalid'" class="secondary" :disabled="busy || !canWrite" @click="recover(article.id)">重新解析已保存的响应</button><details @toggle="showIllustration(article.id,$event)"><summary>阅读全文与引用依据</summary><figure v-if="illustrations[article.id]" class="article-figure"><img :src="illustrations[article.id]" alt="原创资料图解，非产品实拍"><figcaption>原创资料图解 · 非产品实拍</figcaption></figure><div class="article-text">{{ article.body }}</div></details><p class="hint">文章支持导出；选品任务请到“选品到公众号”查看投递阶段、阻断原因与最终回执。</p></section></template>
  <SelectionPipelinePanel v-if="tab==='publishing'" :listings="filteredListings" :ai-configured="!!capabilities.ai_configured" :source-configured="!!capabilities.xianyu_provider_configured" :source-note="capabilities.xianyu_note" :selected-article-id="selectedArticleId" @open-articles="openArticles" />
  <template v-if="tab==='guide'"><section class="research-panel guide"><h2>一篇有依据的数码选购文章</h2><ol><li><strong>拿到真实商品资料。</strong>先公开采集；页面要求登录时，配置授权数据接口或导入已有资料。</li><li><strong>只比较相同设备。</strong>型号、容量、内存、成色不同的商品分组计算，价格包括运费。</li><li><strong>先看风险再看低价。</strong>故障、锁机、订金和过期样本不会成为正常低价推荐。</li><li><strong>写出适用边界。</strong>五个样本、三个卖家只是最低门槛；挂牌价不代表成交价，卖家描述不代表已验机。</li><li><strong>核对后再发布。</strong>保留原链接与观察时间；可导出 Markdown / HTML；在“选品到公众号”选择交付方式，自动校验后投递并查询结果。</li></ol><h3>独立项目</h3><p>本项目独立构建、部署与存储数码研究数据。登录和既有公众号运营通过公共服务接口复用。完整技术文档在独立项目的 docs 目录。</p></section></template>
 </main>
</template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref} from 'vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
import SelectionPipelinePanel from '@/components/wechat/SelectionPipelinePanel.vue'
const auth=useAuthStore(),canWrite=computed(()=>auth.can('wechat.write'))
const illustrations=ref<Record<string,string>>({})
const selectedArticleId=ref('')
function selectForPublication(id:string){selectedArticleId.value=id;tab.value='publishing'}
const tab=ref('market'),busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),filter=ref(''),showImport=ref(false),importMode=ref('form'),importText=ref('')
const listings=ref<any[]>([]),reports=ref<any[]>([]),articles=ref<any[]>([]),sources=ref<any[]>([]),news=ref<any[]>([]),capabilities=ref<any>({})
const tabs=[{id:'market',label:'选购研究'},{id:'sources',label:'来源雷达'},{id:'articles',label:'研究文章'},{id:'publishing',label:'选品到公众号'},{id:'guide',label:'使用说明'}]
const conditionLabel:Record<string,string>={new:'全新',good:'良好',fair:'明显使用痕迹',parts:'故障 / 配件',unknown:'未核实'}
const sourceState:Record<string,string>={available:'可用',stale:'暂无近期内容',unavailable:'暂不可用',unverified:'未检查'}
const articleState:Record<string,string>={ready:'分析稿已生成',needs_review:'需要人工核对',generating:'生成中',uncertain:'调用结果待核对',interrupted:'生成中断',response_invalid:'响应待修复',failed:'模型调用失败'}
const requestId=()=>{const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
const localTime=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const form=reactive({title:'',url:'',model:'',variant:'',price:0,shipping:0,category:'phone',condition:'unknown',seller_ref:'',battery_health:'',repair_status:'unknown',observed_at:localTime(),description:'',inspection_available:false})
const filteredListings=computed(()=>listings.value.filter(x=>(x.model+' '+x.variant+' '+x.title).toLowerCase().includes(filter.value.toLowerCase())))
const formatDate=(value:string)=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'尚未检查'
async function get(path:string){const r:any=await request.get('/research/'+path);if(!r.success)throw Error(r.message||'读取失败');return r.data}
async function load(){try{const values=await Promise.all(['listings','analyses','articles','sources','news','capabilities'].map(get));[listings.value,reports.value,articles.value,sources.value,news.value,capabilities.value]=values}catch(e:any){error.value=e.response?.data?.message||e.message||'读取失败'}}
async function act(work:()=>Promise<unknown>,message='操作已完成'){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await work();await load();notice.value=message}catch(e:any){const detail=e.response?.data?.detail;error.value=e.response?.data?.message||(Array.isArray(detail)?detail.map(x=>`${x.loc.join('.')}：${x.msg}`).join('；'):null)||e.message||'操作失败'}finally{busy.value=false}}
const search=()=>act(()=>request.post('/research/xianyu/search',{query:query.value.trim()}),'商品已保存，下一步可以比较价格与风险。')
async function saveListing(){await act(async()=>{let externalId='';try{externalId=new URL(form.url).searchParams.get('id')||form.url}catch{throw Error('请填写商品原链接')};await request.post('/research/listings/import',{items:[{...form,external_id:externalId,source_id:'xianyu',observed_at:new Date(form.observed_at).toISOString(),battery_health:form.battery_health===''?null:Number(form.battery_health)}]})},'商品资料已保存。')}
const importJson=()=>act(()=>request.post('/research/listings/import',JSON.parse(importText.value)),'商品资料已校验并保存。')
const remove=(id:string)=>act(()=>request.delete('/research/listings/'+id),'商品样本已移除。')
const createReport=()=>act(()=>request.post('/research/analyses',{title:(filter.value||query.value||'数码设备')+'，哪些值得进一步核验？',listing_ids:filteredListings.value.map(x=>x.id)}),'分析完成，报告已保留价格依据与风险。')
const createArticle=(id:string,useAi:boolean)=>act(async()=>{await request.post('/research/articles',{research_id:id,request_id:requestId(),use_ai:useAi},{timeout:150000});tab.value='articles'},'文章处理结果已保存，请查看状态。')
const writeNews=(item:any)=>act(async()=>{await request.post('/research/news/articles',{urls:[item.url],title:item.title.slice(0,100),request_id:requestId(),use_ai:true},{timeout:150000});tab.value='articles'},'选题文章处理结果已保存，请核对内容。')
const recover=(id:string)=>act(()=>request.post('/research/articles/'+id+'/recover-response'),'已从保存的响应恢复文章，没有再次调用模型。')
const refreshSource=(id:string)=>act(()=>request.post('/research/sources/'+id+'/refresh'),'来源状态已更新。')
async function download(id:string,format:string){await act(async()=>{const blob=await request.get(`/research/articles/${id}/export`,{params:{format},responseType:'blob'}) as unknown as Blob;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`研究文章-${id}.${format==='html'?'html':'md'}`;a.click();URL.revokeObjectURL(url)},'文章已导出。')}
async function showIllustration(id:string,event:Event){if(!(event.target as HTMLDetailsElement).open||illustrations.value[id])return;try{const blob=await request.get('/research/articles/'+id+'/illustration',{responseType:'blob'}) as unknown as Blob;illustrations.value[id]=URL.createObjectURL(blob)}catch{error.value='正文图解暂时不可用，请稍后重试'}}
onBeforeUnmount(()=>Object.values(illustrations.value).forEach(URL.revokeObjectURL))
async function openArticles(){tab.value='articles';await load()}
onMounted(load)
</script>
